use std::collections::{BinaryHeap, HashMap};
use std::cmp::Reverse;

struct DualHeap {
    small: BinaryHeap<i32>,               // max heap
    large: BinaryHeap<Reverse<i32>>,      // min heap
    delayed: HashMap<i32, i32>,           // counts of elements to remove
    k: usize,
    small_size: usize,
    large_size: usize,
}

impl DualHeap {
    fn new(k: usize) -> Self {
        Self {
            small: BinaryHeap::new(),
            large: BinaryHeap::new(),
            delayed: HashMap::new(),
            k,
            small_size: 0,
            large_size: 0,
        }
    }

    fn prune_small(&mut self) {
        while let Some(&top) = self.small.peek() {
            if let Some(&count) = self.delayed.get(&top) {
                if count > 0 {
                    self.delayed.insert(top, count - 1);
                    if self.delayed[&top] == 0 {
                        self.delayed.remove(&top);
                    }
                    self.small.pop();
                    self.small_size -= 1;
                } else {
                    break;
                }
            } else {
                break;
            }
        }
    }

    fn prune_large(&mut self) {
        while let Some(&Reverse(top)) = self.large.peek() {
            if let Some(&count) = self.delayed.get(&top) {
                if count > 0 {
                    self.delayed.insert(top, count - 1);
                    if self.delayed[&top] == 0 {
                        self.delayed.remove(&top);
                    }
                    self.large.pop();
                    self.large_size -= 1;
                } else {
                    break;
                }
            } else {
                break;
            }
        }
    }

    fn balance(&mut self) {
        // balance sizes: small_size >= large_size and difference <= 1
        if self.small_size > self.large_size + 1 {
            // move top from small to large
            let val = self.small.pop().unwrap();
            self.small_size -= 1;
            self.large.push(Reverse(val));
            self.large_size += 1;
            self.prune_small();
        } else if self.small_size < self.large_size {
            // move top from large to small
            let Reverse(val) = self.large.pop().unwrap();
            self.large_size -= 1;
            self.small.push(val);
            self.small_size += 1;
            self.prune_large();
        }
    }

    fn insert(&mut self, num: i32) {
        if self.small.is_empty() || num <= *self.small.peek().unwrap() {
            self.small.push(num);
            self.small_size += 1;
        } else {
            self.large.push(Reverse(num));
            self.large_size += 1;
        }
        self.balance();
    }

    fn erase(&mut self, num: i32) {
        *self.delayed.entry(num).or_insert(0) += 1;
        if !self.small.is_empty() && num <= *self.small.peek().unwrap() {
            self.small_size -= 1;
            if *self.small.peek().unwrap() == num {
                self.prune_small();
            }
        } else {
            self.large_size -= 1;
            if !self.large.is_empty() && self.large.peek().map(|&Reverse(x)| x) == Some(num) {
                self.prune_large();
            }
        }
        self.balance();
    }

    fn get_median(&self) -> f64 {
        if self.k % 2 == 1 {
            *self.small.peek().unwrap() as f64
        } else {
            (*self.small.peek().unwrap() as f64 + self.large.peek().unwrap().0 as f64) / 2.0
        }
    }
}

pub struct Solution;

impl Solution {
    pub fn median_sliding_window(nums: Vec<i32>, k: i32) -> Vec<f64> {
        let k = k as usize;
        let mut dh = DualHeap::new(k);
        let n = nums.len();
        let mut result = Vec::with_capacity(n - k + 1);

        for i in 0..k {
            dh.insert(nums[i]);
        }
        result.push(dh.get_median());

        for i in k..n {
            dh.insert(nums[i]);
            dh.erase(nums[i - k]);
            result.push(dh.get_median());
        }

        result
    }
}

